// ─── Accessible labels ───────────────────────────────────────────────────────

const ARIA_LABELS = {
  verified:     'Verified',
  pin:          'Pinned',
  favorite:     'Favourite',
  add:          'Add user',
  remove:       'Remove user',
  notification: 'Notification',
};

// ─── SVG badge contents per type ────────────────────────────────────────────

// Circle badge: white Stroke ellipse (r=14) + colored BG ellipse (r=12) + icon
function CircleBadge({ bgVar, children }) {
  return (
    <>
      {/* Stroke: white separation ring — surface/neutral/white */}
      <ellipse cx="16" cy="16" rx="14" ry="14" fill="var(--color-surface-neutral-white)" />
      {/* BG: colored circle */}
      <ellipse cx="16" cy="16" rx="12" ry="12" fill={`var(${bgVar})`} />
      {/* Icon: white fill via text/neutral/inverse */}
      {children}
    </>
  );
}

const BADGE_CONTENTS = {
  // Verified: octagonal badge shape — unique Stroke + BG paths, checkmark icon
  // Stroke 27×27 at (2,2) · BG 23×23 at (4,4) · Check 10×8 at (11,12)
  verified: () => (
    <>
      <path transform="translate(2,2)" d={VERIFIED_STROKE} fill="var(--color-surface-neutral-white)" />
      <path transform="translate(4,4)" d={VERIFIED_BG}     fill="var(--status-sky-base)" />
      <path transform="translate(11,12)" d={VERIFIED_CHECK} fill="var(--color-text-neutral-inverse)" />
    </>
  ),

  // Pin: circle badge · feature/purple · pin icon 14×14 at (9,8)
  pin: () => (
    <CircleBadge bgVar="--status-feature-base">
      <path transform="translate(9,8)" d={PIN_ICON} fill="var(--color-text-neutral-inverse)" />
    </CircleBadge>
  ),

  // Favorite: circle badge · success/green · star icon 16×15 at (8,8)
  favorite: () => (
    <CircleBadge bgVar="--status-success-base">
      <path transform="translate(8,8)" d={STAR_ICON} fill="var(--color-text-neutral-inverse)" />
    </CircleBadge>
  ),

  // Add: circle badge · text/neutral/muted · plus icon 12×12 at (10,10)
  add: () => (
    <CircleBadge bgVar="--color-text-neutral-muted">
      <path transform="translate(10,10)" d={PLUS_ICON} fill="var(--color-text-neutral-inverse)" />
    </CircleBadge>
  ),

  // Remove: circle badge · danger/red · X icon 10×10 at (11,11)
  remove: () => (
    <CircleBadge bgVar="--status-danger-base">
      <path transform="translate(11,11)" d={CLOSE_ICON} fill="var(--color-text-neutral-inverse)" />
    </CircleBadge>
  ),

  // Notification: white circle (r=8) + red dot (r=6) — no bell icon (per DS source)
  // White BG 16×16 at (8,8) · Red dot 12×12 at (10,10) · both centered at (16,16)
  notification: () => (
    <>
      <circle cx="16" cy="16" r="8" fill="var(--color-surface-neutral-white)" />
      <circle cx="16" cy="16" r="6" fill="var(--status-danger-base)" />
    </>
  ),
};

// ─── Component ───────────────────────────────────────────────────────────────

/**
 * @param {object} props
 * @param {'verified'|'pin'|'favorite'|'add'|'remove'|'notification'} props.type
 * @param {string} [props.className] — Additional class names (e.g. 'avatar__top-status' for positioning)
 */
export default function TopStatus({ type, className = '' }) {
  if (!type || !BADGE_CONTENTS[type]) return null;

  const renderContents = BADGE_CONTENTS[type];
  const label = ARIA_LABELS[type] ?? type;

  return (
    <span
      className={`top-status top-status--${type}${className ? ` ${className}` : ''}`}
      role="img"
      aria-label={label}
    >
      <svg
        viewBox="0 0 32 32"
        width="100%"
        height="100%"
        xmlns="http://www.w3.org/2000/svg"
        aria-hidden="true"
      >
        {renderContents()}
      </svg>
    </span>
  );
}
